          </div>
        </div>

        <div className="sidebar-content">
          <div style={{ padding: '0.5rem', fontSize: '0.625rem', textTransform: 'uppercase', letterSpacing: '0.1em', color: 'hsl(var(--muted-foreground))', fontWeight: 600 }}>Navigation</div>

          <nav style={{ display: 'flex', flexDirection: 'column', gap: '0.25rem' }}>
            <a href="#" style={{display: 'flex', alignItems: 'center', gap: '0.5rem', padding: '0.5rem 0.75rem', borderRadius: '0.75rem', fontSize: '0.875rem', fontWeight: 600, color: 'hsl(var(--primary))', backgroundColor: 'hsl(var(--primary) / 0.1)', transition: 'all 0.2s', boxShadow: 'var(--shadow-soft)'}}>
              <MdOutlineDashboard size={18} /> Home
            </a>
            <a href="#" style={{display: 'flex', alignItems: 'center', gap: '0.5rem', padding: '0.5rem 0.75rem', borderRadius: '0.75rem', fontSize: '0.875rem', color: 'hsl(var(--sidebar-foreground))', transition: 'all 0.2s'}} className="hover-lift">
              <MdHelpOutline size={18} /> FAQ
            </a>
            <a href="#" style={{display: 'flex', alignItems: 'center', gap: '0.5rem', padding: '0.5rem 0.75rem', borderRadius: '0.75rem', fontSize: '0.875rem', color: 'hsl(var(--sidebar-foreground))', transition: 'all 0.2s'}} className="hover-lift">
              <MdOutlineAssignment size={18} /> Application Status
