            <a href="#" style={{display: 'flex', alignItems: 'center', gap: '0.5rem', padding: '0.5rem 0.75rem', borderRadius: '0.75rem', fontSize: '0.875rem', color: 'hsl(var(--sidebar-foreground))', transition: 'all 0.2s'}} className="hover-lift">
