import React, { useState, useEffect } from 'react';
import { LuAlertCircle } from "react-icons/lu";

export default function AutomationModal({ isOpen, eventData, onSubmit }) {
  const [inputValue, setInputValue] = useState("");
  const [captchaSrc, setCaptchaSrc] = useState("");
  const [multiInputValues, setMultiInputValues] = useState({});

  useEffect(() => {
    setInputValue("");
    setMultiInputValues({});
    setCaptchaSrc("");

    if (eventData?.type === 'REQUEST_CAPTCHA') {
      if (eventData.image) {
        setCaptchaSrc(eventData.image);
      } else {
        fetch(`http://localhost:8000/automation/captcha-b64?t=${Date.now()}`)
          .then(r => r.json())
          .then(d => { if (d.image) setCaptchaSrc(d.image); })
          .catch(err => console.error("[Captcha] Failed to load:", err));
      }
    }

    if (eventData?.type === 'REQUEST_MISSING_DETAILS' && eventData.missing_fields) {
      const initialMulti = {};
      eventData.missing_fields.forEach(f => initialMulti[f] = "");
      setMultiInputValues(initialMulti);
    }
  }, [eventData]);

  if (!isOpen || !eventData) return null;

  const handleSubmit = (e) => {
    e.preventDefault();
    if (eventData.type === 'REQUEST_MISSING_DETAILS') {
      const allFilled = Object.values(multiInputValues).every(val => val.trim() !== "");
      if (!allFilled) return;
      onSubmit(multiInputValues);
    } else {
      if (!inputValue.trim()) return;
      onSubmit(inputValue);
    }
  };

  const handleMultiChange = (field, value) => {
    setMultiInputValues(prev => ({ ...prev, [field]: value }));
  };

  return (
    <div className="overlay">
      <div className="modal-card">
        <div style={{ display: "flex", alignItems: "center", gap: "0.5rem", marginBottom: "1rem" }}>
          <div style={{ display: "flex", alignItems: "center", justifyContent: "center", width: "2rem", height: "2rem", borderRadius: "0.5rem", backgroundColor: "hsl(var(--primary)/0.1)", color: "hsl(var(--primary))" }}>
            <LuAlertCircle size={20} />
          </div>
          <h2 style={{ fontSize: "1.125rem", fontWeight: 700, margin: 0 }}>Action Required</h2>
        </div>

        <p style={{ fontSize: "0.875rem", color: "hsl(var(--muted-foreground))", marginBottom: "1.5rem" }}>{eventData.message}</p>

        {eventData.type === 'REQUEST_CAPTCHA' && (
          <div style={{ backgroundColor: "hsl(var(--secondary)/0.5)", padding: "1rem", borderRadius: "0.75rem", marginBottom: "1.5rem", textAlign: "center", border: "1px solid hsl(var(--border))" }}>
            {captchaSrc
              ? <img src={captchaSrc} alt="Captcha" style={{ maxWidth: "100%", height: "auto", borderRadius: "0.5rem" }} />
              : <p style={{ color: "hsl(var(--muted-foreground))", fontSize: "0.75rem", margin: 0 }}>Loading captcha...</p>
            }
          </div>
        )}

        {eventData.type === 'REQUEST_MISSING_DETAILS' ? (
          <form onSubmit={handleSubmit} style={{ display: "flex", flexDirection: "column", gap: "1rem" }}>
            {eventData.missing_fields?.map((field, idx) => (
              <div key={idx} style={{ display: "flex", flexDirection: "column" }}>
                <label style={{ fontSize: "0.75rem", fontWeight: 600, color: "hsl(var(--foreground))", marginBottom: "0.25rem", textTransform: "capitalize" }}>{field.replace(/_/g, ' ')}</label>
                <input 
                  type="text" 
                  value={multiInputValues[field] || ""}
                  onChange={(e) => handleMultiChange(field, e.target.value)}
                  placeholder={`Enter ${field.replace(/_/g, ' ')}`}
                  style={{ width: "100%", padding: "0.75rem", borderRadius: "0.75rem", border: "1px solid hsl(var(--border))", backgroundColor: "transparent", fontSize: "0.875rem", color: "hsl(var(--foreground))", outline: "none", boxSizing: "border-box" }}
                  autoFocus={idx === 0}
                />
              </div>
            ))}
            <button type="submit" className="btn-primary" style={{ width: "100%", marginTop: "0.5rem" }}>Submit Details</button>
          </form>
        ) : (
          <form onSubmit={handleSubmit} style={{ display: "flex", flexDirection: "column", gap: "1rem" }}>
            <input 
              type="text" 
              value={inputValue}
              onChange={(e) => setInputValue(e.target.value)}
              placeholder={
                eventData.type === 'REQUEST_CAPTCHA' ? "Enter Captcha" :
                eventData.type === 'REQUEST_OTP'     ? "Enter OTP" :
                eventData.type === 'REQUEST_RESUME'  ? "Type anything to continue..." :
                "Enter value"
              }
              style={{ padding: "0.75rem", borderRadius: "0.75rem", border: "1px solid hsl(var(--border))", backgroundColor: "transparent", fontSize: "0.875rem", color: "hsl(var(--foreground))", outline: "none", boxSizing: "border-box", width: "100%" }}
              autoFocus
            />
            <button type="submit" className="btn-primary" style={{ width: "100%" }}>
              {eventData.type === 'REQUEST_RESUME' ? "Continue" : "Submit"}
            </button>
          </form>
        )}
      </div>
    </div>
  );
}

import { useState } from "react";
import { MdOutlineCloudUpload, MdDeleteOutline } from "react-icons/md";
import { LuCheckCircle2, LuChevronDown, LuChevronUp, LuAlertCircle } from "react-icons/lu";

// ── Reusable floating-label input ─────────────────────────────────────────────
function FloatingInput({ label, name, type = "text", value, onChange, maxLength }) {
  const [focused, setFocused] = useState(false);
  const active = focused || !!value;

  return (
    <div style={{ position: "relative", flex: "1", minWidth: "180px", marginBottom: "0.5rem" }}>
      <label
        style={{
          position: "absolute",
          left: active ? "10px" : "12px",
          top: active ? "-9px" : "50%",
          transform: active ? "translateY(0)" : "translateY(-50%)",
          fontSize: active ? "11px" : "14px",
          color: active ? "hsl(var(--primary))" : "hsl(var(--muted-foreground))",
          backgroundColor: active ? "hsl(var(--card))" : "transparent",
          padding: active ? "0 4px" : "0",
          pointerEvents: "none",
          transition: "all 0.2s ease",
          fontWeight: active ? 600 : 400,
          zIndex: 1,
          whiteSpace: "nowrap",
        }}
      >
        {label}
      </label>
      <input
        type={type}
        name={name}
        value={value}
        onChange={onChange}
        onFocus={() => setFocused(true)}
        onBlur={() => setFocused(false)}
        maxLength={maxLength}
        style={{
          width: "100%",
          padding: "12px 14px",
          borderRadius: "12px",
          border: `1px solid ${focused ? "hsl(var(--primary))" : "hsl(var(--border))"}`,
          backgroundColor: "hsl(var(--card))",
          fontSize: "14px",
          color: "hsl(var(--foreground))",
          outline: "none",
          transition: "border-color 0.2s ease, box-shadow 0.2s ease",
          boxSizing: "border-box",
          boxShadow: focused ? "0 0 0 2px hsl(var(--primary) / 0.1)" : "none"
        }}
      />
    </div>
  );
}
// ─────────────────────────────────────────────────────────────────────────────

export default function DocumentChecklist({ onProceed, onExit, isProceeding, onOpenSocket }) {
  const [checkedItems, setCheckedItems] = useState({
    aadharCard: false,
    rationCard: false,
    photo: false,
    drivingLicense: false,
  });

  const [expandedItem, setExpandedItem] = useState(null);
  const [uploadedFiles, setUploadedFiles] = useState({});
  const [rawFiles, setRawFiles] = useState({});
  const [extractedData, setExtractedData] = useState({});
  const [isUploading, setIsUploading] = useState({});
  const [uploadError, setUploadError] = useState(null);

  const [bulkResults, setBulkResults] = useState(null);
  const [playwrightPayload, setPlaywrightPayload] = useState(null);
  const [submitError, setSubmitError] = useState(null);
  const [isExtracting, setIsExtracting] = useState(false);

  const [credentials, setCredentials] = useState({
    username: "",
    password: "",
    can_number: "",
    aadhar_number: ""
  });

  const [addressDetails, setAddressDetails] = useState({
    village: "",
    building_no: "",
    street_name: "",
    pincode: "",
    from_date: "",
    to_date: ""
  });

  const documents = [
    { id: "aadharCard", label: "Aadhar card" },
    { id: "rationCard", label: "Ration card" },
    { id: "photo", label: "Applicant Photograph" },
    { id: "drivingLicense", label: "Driving license" },
  ];

  const handleCredChange = (e) => setCredentials({ ...credentials, [e.target.name]: e.target.value });
  const handleAddrChange = (e) => setAddressDetails({ ...addressDetails, [e.target.name]: e.target.value });

  const toggleExpand = (id) => {
    setExpandedItem((prev) => (prev === id ? null : id));
    setUploadError(null);
  };

  const handleRemoveFile = (id) => {
    setUploadedFiles((prev) => { const u = { ...prev }; delete u[id]; return u; });
    setRawFiles((prev) => { const u = { ...prev }; delete u[id]; return u; });
    setExtractedData((prev) => { const u = { ...prev }; delete u[id]; return u; });
    setCheckedItems((prev) => ({ ...prev, [id]: false }));
  };

  const handleFileUpload = async (e, id) => {
    const file = e.target.files[0];
    if (!file) return;

    setIsUploading((prev) => ({ ...prev, [id]: true }));
    setUploadError(null);

    const formData = new FormData();
    formData.append("file", file);

    const extUrl =
      id === "photo"
        ? "http://localhost:8002/verify/photo"
        : "http://localhost:8002/extract";

    try {
      const response = await fetch(extUrl, { method: "POST", body: formData });

      if (response.ok) {
        const data = await response.json();

        if (id === "photo" && data.is_human_photo === false) {
          throw new Error("Invalid Photograph. Please ensure the image clearly shows a human person.");
        }

        if (id !== "photo" && data.extracted_data && data.extracted_data.length > 0) {
          setExtractedData((prev) => ({ ...prev, [id]: data.extracted_data }));
        }

        setUploadedFiles((prev) => ({ ...prev, [id]: file.name }));
        setRawFiles((prev) => ({ ...prev, [id]: file }));
        setCheckedItems((prev) => ({ ...prev, [id]: true }));
        setExpandedItem(null);
      } else {
        throw new Error("Server error handling upload.");
      }
    } catch (err) {
      console.error("Upload failed:", err);
      setUploadError(err.message || "Upload Failed. Please try again.");
    } finally {
      setIsUploading((prev) => ({ ...prev, [id]: false }));
    }
  };

  const isAllChecked = Object.values(checkedItems).every(Boolean);

  const handleProceedClick = async () => {
    setSubmitError(null);
    setIsExtracting(true);

    const formData = new FormData();
    if (rawFiles.aadharCard) formData.append("aadhaar", rawFiles.aadharCard);
    if (rawFiles.rationCard) formData.append("ration", rawFiles.rationCard);
    if (rawFiles.drivingLicense) formData.append("driving", rawFiles.drivingLicense);
    if (rawFiles.photo) formData.append("photo", rawFiles.photo);

    try {
      const bulkRes = await fetch("http://localhost:8002/process-all", { method: "POST", body: formData });
      if (!bulkRes.ok) throw new Error(`Document extraction failed (HTTP ${bulkRes.status})`);
      const bulkData = await bulkRes.json();

      if (bulkData.status === "success" && bulkData.result) {
        setBulkResults(bulkData.result);
        const combined = bulkData.result.combined;

        const aadharNum = (credentials.aadhar_number || (combined.aadhaar_number || "")).replace(/\s/g, '');
        const payload = {
          credentials: {
            username: credentials.username,
            password: credentials.password
          },
          applicant_details: {
            can_number:     credentials.can_number   || "",
            aadhar_number:  aadharNum,
            dob:            combined.dob             || "",
            ration_card_no: combined.ration_card_number || "",
            name:           combined.username        || "",
            father_name:    combined.father_name     || "",
            gender:         combined.gender          || "",
            religion:       combined.religion        || "",
            community:      combined.community       || "",
            mobile_number:  combined.phone_number    || "",
            email:          combined.email           || ""
          },
          address_details: {
            state:        combined.state        || "Tamil Nadu",
            district:     combined.district     || "",
            village:      combined.taluk        || combined.district || "",
            area:         combined.area         || "",
            building_no:  combined.door_no      || "",
            street_name:  combined.street_name  || combined.area   || "",
            pincode:      combined.pincode      || "",
            from_date:    addressDetails.from_date,
            to_date:      addressDetails.to_date,
            perm_state:        combined.state        || "Tamil Nadu",
            perm_district:     combined.district     || "",
            perm_village:      combined.taluk        || combined.district || "",
            perm_building_no:  combined.door_no      || "",
            perm_street_name:  combined.street_name  || combined.area   || "",
            perm_pincode:      combined.pincode      || ""
          },
          documents: {
            photo_path:            bulkData.saved_paths?.["Photo"]   || "",
            self_decl_path:        "",
            aadhaar_path:          bulkData.saved_paths?.["Aadhaar"] || "",
            address_proof_path:    bulkData.saved_paths?.["Driving License"] || "",
            address_doc_no:        combined.dl_number || ""
          }
        };

        if (onOpenSocket) await onOpenSocket();

        for (let i = 0; i < 10; i++) {
          try {
            const statusRes = await fetch("http://localhost:8000/ws/status");
            const statusData = await statusRes.json();
            if (statusData.connected) break;
          } catch (_) {}
          await new Promise(r => setTimeout(r, 500));
        }

        setPlaywrightPayload(payload);

        const submitRes = await fetch("http://localhost:8000/submit-application", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(payload)
        });

        if (!submitRes.ok) {
          throw new Error(`Automation server error (HTTP ${submitRes.status}).`);
        }
      } else {
        throw new Error("Document extraction returned no results. Please check your uploaded files.");
      }
    } catch (e) {
      setSubmitError(e.message || "An unexpected error occurred. Please try again.");
    } finally {
      setIsExtracting(false);
    }
  };

  const isFormValid = isAllChecked &&
                      credentials.username &&
                      credentials.password &&
                      addressDetails.from_date &&
                      addressDetails.to_date;

  if (bulkResults) {
    const p = playwrightPayload;
    const Row = ({ label, value, isExtracted }) => (
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", padding: "0.5rem 0", borderBottom: "1px solid hsl(var(--border))", fontSize: "0.875rem" }}>
        <span style={{ color: "hsl(var(--muted-foreground))", fontWeight: 500, display: "flex", gap: "0.5rem", alignItems: "center" }}>
          {label}
          {isExtracted !== undefined && (
            <span style={{ fontSize: "0.625rem", padding: "0.125rem 0.375rem", borderRadius: "0.375rem", backgroundColor: isExtracted ? "hsl(var(--primary)/0.1)" : "hsl(var(--status-online)/0.1)", color: isExtracted ? "hsl(var(--primary))" : "hsl(var(--status-online))", fontWeight: 700, textTransform: "uppercase" }}>
              {isExtracted ? "Extracted" : "Input"}
            </span>
          )}
        </span>
        <span style={{ color: "hsl(var(--foreground))", fontWeight: 600, textAlign: "right", maxWidth: "60%", wordBreak: "break-all" }}>
          {value || <span style={{ color: "hsl(var(--muted-foreground)/0.5)" }}>—</span>}
        </span>
      </div>
    );

    const Section = ({ title, children }) => (
      <div style={{ backgroundColor: "hsl(var(--card))", border: "1px solid hsl(var(--border))", borderRadius: "1rem", padding: "1.25rem", marginBottom: "1rem", boxShadow: "var(--shadow-card)" }}>
        <h4 style={{ fontSize: "0.75rem", fontWeight: 700, textTransform: "uppercase", letterSpacing: "0.1em", color: "hsl(var(--primary))", marginBottom: "0.75rem" }}>{title}</h4>
        {children}
      </div>
    );

    return (
      <div className="animate-fade-in-up" style={{ maxHeight: "72vh", overflowY: "auto", backgroundColor: "hsl(var(--card))", borderRadius: "1.5rem", padding: "1.5rem", border: "1px solid hsl(var(--border))", boxShadow: "var(--shadow-elevated)" }}>
        <div style={{ display: "flex", alignItems: "center", gap: "0.5rem", marginBottom: "0.5rem" }}>
          <LuCheckCircle2 size={24} color="hsl(var(--primary))" />
          <h3 style={{ fontSize: "1.25rem", fontWeight: 700, color: "hsl(var(--foreground))", margin: 0 }}>Processing Complete</h3>
        </div>
        <p style={{ fontSize: "0.875rem", color: "hsl(var(--muted-foreground))", marginBottom: "1.5rem" }}>Review the data sent to Playwright below. Automation has started in the background.</p>

        <Section title="Validation Summary">
          <Row label="Name Match" value={`${bulkResults.validation?.name_similarity?.toFixed(1) ?? "—"}%`} />
          <Row label="DOB Match" value={bulkResults.validation?.dob_match ? "Yes" : "No"} />
          <Row label="Confidence Score" value={`${bulkResults.confidence_score ?? "—"}%`} />
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", paddingTop: "0.5rem", fontSize: "0.875rem" }}>
            <span style={{ color: "hsl(var(--muted-foreground))", fontWeight: 500 }}>Status</span>
            <span style={{ fontWeight: 800, color: bulkResults.validation?.name_match ? "hsl(var(--primary))" : "hsl(var(--destructive))" }}>
              {bulkResults.validation?.name_match ? "APPROVED" : "REVIEW REQUIRED"}
            </span>
          </div>
        </Section>

        {p && (
          <>
            <Section title="Portal Credentials">
              <Row label="Username" value={p.credentials?.username} isExtracted={false} />
              <Row label="Password" value={"•".repeat((p.credentials?.password || "").length)} isExtracted={false} />
            </Section>

            <Section title="Applicant Details">
              <Row label="Name" value={p.applicant_details?.name} isExtracted={true} />
              <Row label="Father Name" value={p.applicant_details?.father_name} isExtracted={true} />
              <Row label="Gender" value={p.applicant_details?.gender} isExtracted={true} />
              <Row label="Aadhaar Number" value={p.applicant_details?.aadhar_number} isExtracted={false} />
              <Row label="Date of Birth" value={p.applicant_details?.dob} isExtracted={true} />
            </Section>
          </>
        )}

        <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginTop: "1.5rem", paddingTop: "1.5rem", borderTop: "1px solid hsl(var(--border))" }}>
          <div style={{ fontSize: "0.75rem", color: "hsl(var(--muted-foreground))", display: "flex", alignItems: "center", gap: "0.5rem" }}>
            <span className="animate-pulse" style={{ width: "8px", height: "8px", borderRadius: "50%", backgroundColor: "hsl(var(--primary))" }}></span>
            Playwright running in background...
          </div>
          <button className="btn-secondary" onClick={() => { if (onProceed) onProceed(); else onExit(); }}>Close details</button>
        </div>
      </div>
    );
  }

  return (
    <div className="animate-fade-in-up" style={{ maxHeight: '72vh', overflowY: 'auto', backgroundColor: "hsl(var(--card))", borderRadius: "1.5rem", padding: "1.5rem", border: "1px solid hsl(var(--border))", boxShadow: "var(--shadow-card)" }}>
      <h3 style={{ fontSize: "1.25rem", fontWeight: 700, color: "hsl(var(--foreground))", marginBottom: "1.5rem", fontFamily: "'Plus Jakarta Sans', sans-serif" }}>TNeSevai Application Details</h3>

      {/* ── Section 1: Portal Credentials ── */}
      <form onSubmit={(e) => e.preventDefault()} autoComplete="on">
        <div style={{ marginBottom: "1.5rem", padding: "1.25rem", backgroundColor: "hsl(var(--sidebar-background))", border: "1px solid hsl(var(--border))", borderRadius: "1rem" }}>
          <h4 style={{ fontSize: "0.875rem", fontWeight: 600, color: "hsl(var(--foreground))", marginBottom: "1rem" }}>1. Portal Credentials</h4>
          <div style={{ display: "flex", gap: "1rem", flexWrap: "wrap" }}>
            <FloatingInput label="TNeSevai Username" name="username" value={credentials.username} onChange={handleCredChange} />
            <FloatingInput label="Password" name="password" type="password" value={credentials.password} onChange={handleCredChange} />
            <FloatingInput label="CAN Number" name="can_number" value={credentials.can_number} onChange={handleCredChange} />
            <FloatingInput label="Aadhar Number *" name="aadhar_number" value={credentials.aadhar_number} onChange={handleCredChange} maxLength={12} />
          </div>
        </div>
      </form>

      {/* ── Section 2: Residency Constraints ── */}
      <div style={{ marginBottom: "1.5rem", padding: "1.25rem", backgroundColor: "hsl(var(--sidebar-background))", border: "1px solid hsl(var(--border))", borderRadius: "1rem" }}>
        <h4 style={{ fontSize: "0.875rem", fontWeight: 600, color: "hsl(var(--foreground))", marginBottom: "1rem" }}>2. Residency Constraints</h4>
        <div style={{ display: "flex", gap: "1rem", flexWrap: "wrap" }}>
          <FloatingInput label="Residing From (DD/MM/YYYY)" name="from_date" value={addressDetails.from_date} onChange={handleAddrChange} />
          <FloatingInput label="Residing To (DD/MM/YYYY)" name="to_date" value={addressDetails.to_date} onChange={handleAddrChange} />
        </div>
      </div>

      {/* ── Section 3: Document Checklist ── */}
      <h4 style={{ fontSize: "0.875rem", fontWeight: 600, color: "hsl(var(--foreground))", marginBottom: "0.5rem" }}>3. Document Checklist</h4>
      <p style={{ fontSize: "0.875rem", color: "hsl(var(--muted-foreground))", marginBottom: "1rem" }}>Ensure all required documents are ready for extraction & upload:</p>

      <div style={{ display: "flex", flexDirection: "column", gap: "0.75rem", marginBottom: "1.5rem" }}>
        {documents.map((doc) => {
          const isChecked = checkedItems[doc.id];
          const isExpanded = expandedItem === doc.id;

          return (
            <div key={doc.id} style={{ 
              backgroundColor: isChecked ? "hsl(var(--primary)/0.02)" : "hsl(var(--card))", 
              border: `1px solid ${isChecked ? "hsl(var(--primary)/0.3)" : "hsl(var(--border))"}`, 
              borderRadius: "1rem", 
              overflow: "hidden", 
              transition: "all 0.3s ease" 
            }}>
              <div 
                onClick={() => toggleExpand(doc.id)}
                style={{ display: "flex", alignItems: "center", justifyContent: "space-between", padding: "1rem 1.25rem", cursor: "pointer", backgroundColor: isExpanded ? "hsl(var(--secondary)/0.5)" : "transparent" }}
              >
                <div style={{ display: "flex", alignItems: "center", gap: "0.875rem" }}>
                  <div style={{ 
                    width: "1.5rem", height: "1.5rem", 
                    borderRadius: "0.5rem", 
                    border: `1.5px solid ${isChecked ? "hsl(var(--primary))" : "hsl(var(--border))"}`, 
                    backgroundColor: isChecked ? "hsl(var(--primary))" : "transparent",
                    display: "flex", alignItems: "center", justifyContent: "center",
                    transition: "all 0.2s"
                  }}>
                    {isChecked && <LuCheckCircle2 size={14} color="white" />}
                  </div>
                  <span style={{ fontSize: "0.875rem", fontWeight: isChecked ? 600 : 500, color: "hsl(var(--foreground))" }}>
                    {doc.label}
                  </span>
                </div>
                {isExpanded ? <LuChevronUp size={18} color="hsl(var(--muted-foreground))" /> : <LuChevronDown size={18} color="hsl(var(--muted-foreground))" />}
              </div>

              {isExpanded && (
                <div className="animate-fade-in-up" style={{ padding: "0 1.25rem 1.25rem 3.65rem" }}>
                  {uploadedFiles[doc.id] ? (
                    <div>
                      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", padding: "0.75rem 1rem", backgroundColor: "hsl(var(--primary)/0.05)", border: "1px solid hsl(var(--primary)/0.2)", borderRadius: "0.75rem", marginBottom: "0.75rem" }}>
                        <div style={{ display: "flex", alignItems: "center", gap: "0.5rem" }}>
                          <LuCheckCircle2 size={16} color="hsl(var(--primary))" />
                          <span style={{ fontSize: "0.875rem", fontWeight: 500, color: "hsl(var(--primary))", wordBreak: "break-all" }}>{uploadedFiles[doc.id]}</span>
                        </div>
                        <button onClick={() => handleRemoveFile(doc.id)} style={{ background: "transparent", border: "none", cursor: "pointer", color: "hsl(var(--muted-foreground))", display: "flex", alignItems: "center", justifyContent: "center" }} title="Remove document">
                          <MdDeleteOutline size={18} className="hover:text-destructive transition-colors" />
                        </button>
                      </div>

                      {extractedData[doc.id] && extractedData[doc.id].map((extract, idx) => (
                        <div key={idx} style={{ padding: "0.75rem", backgroundColor: "hsl(var(--secondary)/0.5)", borderRadius: "0.75rem", fontSize: "0.75rem", color: "hsl(var(--muted-foreground))" }}>
                          <h5 style={{ fontWeight: 600, color: "hsl(var(--foreground))", marginBottom: "0.25rem" }}>{extract.certificate_type} Details</h5>
                          <ul style={{ listStyleType: "none", margin: 0, padding: 0 }}>
                            {Object.entries(extract.extracted_fields || extract)
                              .filter(([k]) => k !== "certificate_type")
                              .map(([key, value]) => (
                                <li key={key} style={{ marginBottom: "0.125rem" }}>
                                  <strong style={{ color: "hsl(var(--foreground))" }}>{key.replace(/_/g, ' ').toUpperCase()}:</strong> {value}
                                </li>
                              ))}
                          </ul>
                        </div>
                      ))}
                    </div>
                  ) : (
                    <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: "0.75rem", padding: "1.5rem", backgroundColor: "hsl(var(--secondary)/0.5)", border: "1.5px dashed hsl(var(--border))", borderRadius: "1rem", textAlign: "center", transition: "all 0.2s" }} className="hover:border-primary/50 hover:bg-primary/5">
                      <MdOutlineCloudUpload size={32} color="hsl(var(--primary)/0.7)" />
                      <div>
                        <p style={{ fontSize: "0.875rem", fontWeight: 500, color: "hsl(var(--foreground))", margin: 0 }}>Upload your {doc.label}</p>
                        <p style={{ fontSize: "0.75rem", color: "hsl(var(--muted-foreground))", margin: 0 }}>PDF, JPG, or PNG (max 5MB)</p>
                      </div>
                      {uploadError && <div style={{ fontSize: "0.75rem", color: "hsl(var(--destructive))", backgroundColor: "hsl(var(--destructive)/0.1)", padding: "0.5rem", borderRadius: "0.5rem", display: "flex", alignItems: "center", gap: "0.25rem" }}><LuAlertCircle size={14}/> {uploadError}</div>}
                      <label style={{ display: "inline-flex", cursor: "pointer" }}>
                        <span className="btn-secondary" style={{ pointerEvents: isUploading[doc.id] ? "none" : "auto", opacity: isUploading[doc.id] ? 0.5 : 1 }}>
                          {isUploading[doc.id] ? "Uploading..." : "Browse Files"}
                        </span>
                        <input type="file" accept=".pdf,.jpg,.jpeg,.png" onChange={(e) => handleFileUpload(e, doc.id)} disabled={isUploading[doc.id]} hidden />
                      </label>
                    </div>
                  )}
                </div>
              )}
            </div>
          );
        })}
      </div>

      {submitError && (
        <div style={{ marginBottom: "1.5rem", padding: "1rem", backgroundColor: "hsl(var(--destructive)/0.1)", border: "1px solid hsl(var(--destructive)/0.2)", borderRadius: "0.75rem", color: "hsl(var(--destructive))", fontSize: "0.875rem", display: "flex", alignItems: "center", gap: "0.5rem" }}>
          <LuAlertCircle size={18} /> {submitError}
        </div>
      )}

      <div style={{ display: "flex", gap: "0.75rem", justifyContent: "flex-end", paddingTop: "1rem", borderTop: "1px solid hsl(var(--border))" }}>
        <button className="btn-secondary" onClick={onExit} disabled={isProceeding || isExtracting}>Exit</button>
        <button className="btn-primary" onClick={handleProceedClick} disabled={!isFormValid || isProceeding || isExtracting}>
          {isExtracting ? "Extracting..." : isProceeding ? "Processing..." : "Proceed to Automation"}
        </button>
      </div>
    </div>
  );
}

import { useState } from "react";
import { LuFileSignature, LuDownload } from "react-icons/lu";

export default function SelfDeclarationModal({ isOpen, downloadPath, onSubmit, onExit }) {
  const [uploadedFile, setUploadedFile] = useState(null);
  const [isUploading, setIsUploading] = useState(false);

  if (!isOpen) return null;

  const handleFileUpload = (e) => {
    const file = e.target.files[0];
    if (file) {
      setUploadedFile(file);
    }
  };

  const handleSubmit = async () => {
    if (!uploadedFile) {
      alert("Please upload the signed Self-Declaration form first!");
      return;
    }

    setIsUploading(true);

    try {
      const formData = new FormData();
      formData.append("file", uploadedFile);

      const response = await fetch("http://localhost:8000/upload-signed-declaration", {
        method: "POST",
        body: formData
      });

      if (!response.ok) {
        throw new Error("Failed to upload signed declaration");
      }

      const data = await response.json();
      onSubmit(data.file_path);
    } catch (error) {
      alert("Failed to upload signed declaration. Please try again.");
      setIsUploading(false);
    }
  };

  const handleDownload = () => {
    window.open(`http://localhost:8000/download-declaration`, '_blank');
  };

  return (
    <div className="overlay">
      <div className="modal-card" style={{ maxWidth: '32rem' }}>
        <div style={{ display: "flex", alignItems: "center", gap: "0.75rem", marginBottom: "1rem" }}>
          <div style={{ display: "flex", alignItems: "center", justifyContent: "center", width: "2.5rem", height: "2.5rem", borderRadius: "0.75rem", backgroundColor: "hsl(var(--primary)/0.1)", color: "hsl(var(--primary))" }}>
            <LuFileSignature size={24} />
          </div>
          <h2 style={{ fontSize: "1.25rem", fontWeight: 700, margin: 0, color: "hsl(var(--foreground))" }}>
            Self-Declaration Form
          </h2>
        </div>

        <p style={{ color: "hsl(var(--muted-foreground))", fontSize: "0.875rem", marginBottom: "1.5rem" }}>
          The Self-Declaration Form has been generated. Please follow these steps:
        </p>

        <ol style={{ fontSize: "0.875rem", color: "hsl(var(--foreground))", paddingLeft: "1.5rem", marginBottom: "1.5rem", display: "flex", flexDirection: "column", gap: "0.5rem" }}>
          <li>Download the form using the button below</li>
          <li>Print the form</li>
          <li>Sign it manually</li>
          <li>Scan or photograph the signed form</li>
          <li>Upload the signed version below</li>
        </ol>

        <button
          onClick={handleDownload}
          className="btn-primary"
          style={{ width: "100%", marginBottom: "1.5rem" }}
        >
          <LuDownload size={16} /> Download Self-Declaration Form
        </button>

        <div style={{ border: "1.5px dashed hsl(var(--border))", borderRadius: "1rem", padding: "1.5rem", textAlign: "center", marginBottom: "1.5rem", backgroundColor: "hsl(var(--secondary)/0.5)", transition: "all 0.2s" }} className="hover:border-primary/50">
          {uploadedFile ? (
            <div>
              <p style={{ color: "hsl(var(--primary))", fontWeight: 600, fontSize: "0.875rem", marginBottom: "0.5rem" }}>
                ✓ {uploadedFile.name}
              </p>
              <button
                onClick={() => setUploadedFile(null)}
                className="btn-secondary"
                style={{ color: "hsl(var(--destructive))", borderColor: "hsl(var(--destructive)/0.2)", backgroundColor: "hsl(var(--destructive)/0.05)" }}
              >
                Remove
              </button>
            </div>
          ) : (
            <div>
              <p style={{ color: "hsl(var(--foreground))", fontWeight: 500, fontSize: "0.875rem", marginBottom: "0.75rem" }}>
                Upload Signed Self-Declaration Form
              </p>
              <label style={{ display: "inline-block", cursor: "pointer" }}>
                <span className="btn-secondary">Choose File</span>
                <input
                  type="file"
                  accept=".pdf,.jpg,.jpeg,.png"
                  onChange={handleFileUpload}
                  style={{ display: "none" }}
                />
              </label>
              <p style={{ fontSize: "0.75rem", color: "hsl(var(--muted-foreground))", marginTop: "0.75rem", marginBottom: 0 }}>
                Supported: PDF, JPG, PNG (max 5MB)
              </p>
            </div>
          )}
        </div>

        <div style={{ display: "flex", gap: "0.75rem" }}>
          <button onClick={onExit} disabled={isUploading} className="btn-secondary" style={{ flex: 1 }}>
            Exit
          </button>
          <button onClick={handleSubmit} disabled={!uploadedFile || isUploading} className="btn-primary" style={{ flex: 2 }}>
            {isUploading ? "Uploading..." : "Submit Signed Form"}
          </button>
        </div>
      </div>
    </div>
  );
}
